-- Feature 27: append-only, local synthetic assurance corpus. Not product certification.
CREATE TABLE IF NOT EXISTS safety_assurance_runs (operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),UNIQUE(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS safety_assurance_verdicts (operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES safety_assurance_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS safety_assurance_roots (operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES safety_assurance_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS safety_assurance_case_results (operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES safety_assurance_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS safety_assurance_mutation_results (operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES safety_assurance_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS safety_assurance_request_claims (operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,root_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE INDEX IF NOT EXISTS safety_assurance_runs_operator_idx ON safety_assurance_runs(operator_test_id,run_hash);
CREATE OR REPLACE FUNCTION safety_assurance_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'safety_assurance_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY(SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_name LIKE 'safety_assurance_%') LOOP EXECUTE format('DROP TRIGGER IF EXISTS safety_assurance_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER safety_assurance_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION safety_assurance_append_only()',t); END LOOP; END $$;
